.sc-tw{
            background-color: #030708;
            color: #f1f5f9;
            font-family: 'Montserrat', sans-serif;
            overflow-x: hidden;
        }.sc-tw .gale-overlay{
            background: linear-gradient(180deg, rgba(3,7,8,0.3) 0%, rgba(3,7,8,0.7) 70%, #030708 100%);
